import{_ as t,o as e,c as o,ak as c}from"./chunks/framework.DxrHb2fb.js";const u=JSON.parse('{"title":"版本与兼容性政策","description":"","frontmatter":{},"headers":[],"relativePath":"guide/versioning.md","filePath":"guide/versioning.md","lastUpdated":1790454556000}'),a={name:"guide/versioning.md"};function r(i,d,n,s,h,l){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="版本与兼容性政策" tabindex="-1">版本与兼容性政策 <a class="header-anchor" href="#版本与兼容性政策" aria-label="Permalink to &quot;版本与兼容性政策&quot;">​</a></h1><p>本页回答一个问题：升级到下一个 <code>1.x</code> 小版本时，已依赖的公开面是否会变化。</p><p>XiHan.UI 的公开面横跨五种介质：替换自带皮肤、手写 Light DOM 结构都是 <a href="./styling">皮肤与样式分层</a> 与 <a href="./anatomy">解剖与部件契约</a> 公开说明的用法：</p><table tabindex="0"><thead><tr><th>介质</th><th>使用者写在哪里</th><th>例子</th></tr></thead><tbody><tr><td>JS / TS 导出</td><td>自己的源码</td><td><code>import { XhSelectRoot } from &#39;@xihan-ui/vue&#39;</code></td></tr><tr><td>解剖属性</td><td>CSS 选择器</td><td><code>[data-scope=&#39;select&#39;][data-part=&#39;trigger&#39;]</code></td></tr><tr><td><code>data-*</code> 状态属性</td><td>CSS 选择器</td><td><code>[data-state=&#39;open&#39;]</code>、<code>[data-tone=&#39;danger&#39;]</code></td></tr><tr><td>CSS 自定义属性与 <code>@layer</code> 名</td><td>自己的样式表</td><td><code>--xh-bg-brand</code>、<code>@layer xihan.overrides</code></td></tr><tr><td>自定义元素标签与 attribute</td><td>自己的 HTML</td><td><code>&lt;xh-dialog modal=&quot;true&quot;&gt;</code>、<code>data-xh-part=&quot;content&quot;</code></td></tr></tbody></table><p>破坏其中任何一种都不会产生编译错误、运行时异常或降级，只会表现为样式丢失或控件不响应。因此本页对五种介质逐类给出结论。</p><h2 id="三个档位" tabindex="-1">三个档位 <a class="header-anchor" href="#三个档位" aria-label="Permalink to &quot;三个档位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>档位</th><th>含义</th></tr></thead><tbody><tr><td><strong>受约束</strong></td><td>改名、删除、收窄语义 = major。新增同类成员 = minor。</td></tr><tr><td><strong>只增不减</strong></td><td>只保证已有成员不消失、不改名。新增字段与条目不算破坏。</td></tr><tr><td><strong>排除</strong></td><td>明确不在承诺内，任何版本都可能改。使用者不应依赖。</td></tr></tbody></table><p>版本号采用语义化版本 <code>major.minor.patch</code>：受约束的成员变更走 major，新增走 minor，只修正行为不改名字走 patch。</p><h2 id="_18-个包必须同版本安装" tabindex="-1">18 个包必须同版本安装 <a class="header-anchor" href="#_18-个包必须同版本安装" aria-label="Permalink to &quot;18 个包必须同版本安装&quot;">​</a></h2><p>18 个包锁步发布：任何一个包发新版本，全部 18 个包一起发同一个号。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@xihan-ui/core     @xihan-ui/position       @xihan-ui/tokens</span></span>\n<span class="line"><span>@xihan-ui/styles   @xihan-ui/headless       @xihan-ui/icons</span></span>\n<span class="line"><span>@xihan-ui/vue      @xihan-ui/web-components @xihan-ui/chat-stream</span></span>\n<span class="line"><span>@xihan-ui/markdown @xihan-ui/code-highlight @xihan-ui/backgrounds</span></span>\n<span class="line"><span>@xihan-ui/sound    @xihan-ui/motion         @xihan-ui/animations</span></span>\n<span class="line"><span>@xihan-ui/pointer  @xihan-ui/viz</span></span></code></pre></div><p>两条后果：</p><ul><li>某个包的 major 可能不含任何针对它自身的变更。<code>@xihan-ui/markdown</code> 升到 <code>2.0.0</code> 可能只是因为 <code>@xihan-ui/vue</code> 修改了一个 prop。判断某次 major 是否影响当前项目，以 <a href="./../changelog">更新日志</a> 的分类条目为准，不以版本号跨度为准。</li><li>不混装版本。<code>@xihan-ui/vue</code> 与 <code>@xihan-ui/headless</code> 版本不一致时类型无法对齐；<code>@xihan-ui/web-components</code> 更严格：同一个 <code>xh-</code> 标签被两个版本注册会直接抛错。适配器与其兄弟包目前是普通 <code>dependencies</code>，包管理器不会阻止这种组合，需要使用方自行保证（见<a href="#尚无门禁的条款">尚无门禁的条款</a>）。</li></ul><hr><h2 id="一、js-ts-导出面" tabindex="-1">一、JS / TS 导出面 <a class="header-anchor" href="#一、js-ts-导出面" aria-label="Permalink to &quot;一、JS / TS 导出面&quot;">​</a></h2><p>18 个包中 18 个出 JS 或类型入口，共 36 个带类型的入口。</p><h3 id="受约束" tabindex="-1">受约束 <a class="header-anchor" href="#受约束" aria-label="Permalink to &quot;受约束&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>说明</th></tr></thead><tbody><tr><td>包名</td><td>18</td><td>把代码从一个包移到另一个包 = major</td></tr><tr><td><code>exports</code> 子路径</td><td>36 个 JS 入口</td><td>如 <code>@xihan-ui/vue/backgrounds</code>、<code>@xihan-ui/web-components/define</code>、<code>@xihan-ui/core/metadata</code>。没有 <code>./*</code> 通配，深路径引用（<code>.../dist/xxx.js</code>）会被 Node 与打包器拒绝，这些路径不是 API</td></tr><tr><td>Vue 组件导出 <code>Xh*</code></td><td>1056（136 个家族）</td><td><code>XhButton</code>、<code>XhSelectRoot</code>、<code>XhSelectItemIndicator</code></td></tr><tr><td>Vue 组合式函数 <code>use&lt;家族&gt;</code></td><td>104</td><td><code>useSelect</code>、<code>useCombobox</code>。不使用库内部件、自行编写标记时的唯一入口</td></tr><tr><td>Vue 指令</td><td>2</td><td><code>vBackground</code>（<code>@xihan-ui/vue/backgrounds</code>）、<code>vSound</code>（<code>@xihan-ui/vue/sound</code>），两个子入口各依赖一个可选 peer</td></tr><tr><td>无头内核 <code>connect*</code></td><td>136</td><td><code>connectAccordion</code> 及其参数顺序、返回的 getter 名</td></tr><tr><td>无头内核 <code>*Machine</code></td><td>80</td><td>机器 schema 的形状</td></tr><tr><td>类型 <code>*Props</code> / <code>*Api</code> / <code>*ChangeDetails</code> / <code>*Schema</code></td><td>145 / 120 / 103 / 80</td><td>删字段、改字段名、把可选改必填都是 major</td></tr><tr><td>Vue prop 名与未传入语义</td><td>373 个不同名字 / 1335 处声明</td><td>见下方说明</td></tr><tr><td>Vue emit 名集合</td><td>67 个不同名字 / 243 处</td><td>名字受约束（列在 <code>emits</code> 中的事件不经 <code>$attrs</code> 透传，删除名字会静默改变行为）</td></tr><tr><td>Vue 插槽名</td><td>12</td><td><code>default</code>、<code>item</code>、<code>label</code>、<code>trigger</code>、<code>panel</code>、<code>content</code>、<code>empty</code>、<code>indicator</code>、<code>mark</code>、<code>cell</code>、<code>split</code>、<code>tooltip</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Vue prop 的未传入语义也是契约</p><p><code>disabled</code> 声明为裸 <code>Boolean</code>（未传入恒为 <code>false</code>）还是 <code>{ type: Boolean, default: undefined }</code>（未传入交由底层状态机决定），在类型上几乎没有差别，但决定了不传该 prop 时组件的表现。仓库中 202 处裸 <code>Boolean</code>、180 处三态、12 处 <code>default: true</code>、1 处显式 <code>default: false</code>。把某个 prop 从一种改为另一种是 major，即使名字和类型都未变。</p></div><h3 id="只增不减" tabindex="-1">只增不减 <a class="header-anchor" href="#只增不减" aria-label="Permalink to &quot;只增不减&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>说明</th></tr></thead><tbody><tr><td>Vue 上下文类型 <code>*Context</code> / <code>*Callbacks</code></td><td>108</td><td>用于给透传的 <code>api</code> 标注类型。只保证可读，不保证可构造：新增可选字段不算破坏，因此不要写 <code>const c: SelectContext = { … }</code> 这类字面量赋值</td></tr><tr><td><code>custom-elements.json</code>（CEM）</td><td>1 份 / 138 个元素</td><td>已经进过清单的 <code>tagName</code> / <code>attribute</code> / <code>event</code> 条目不会消失；<code>cssProperties</code>（皮肤覆盖槽）与 <code>events</code> 的 <code>type</code>（detail 类型）由 <code>scripts/enrich-cem.mjs</code> 从皮肤与元素源码生成，<code>gate:cem</code> 校验同步。字段结构细节仍不承诺，补充算 minor</td></tr></tbody></table><h3 id="排除" tabindex="-1">排除 <a class="header-anchor" href="#排除" aria-label="Permalink to &quot;排除&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>排除原因</th></tr></thead><tbody><tr><td><code>@xihan-ui/headless</code> 的内部算子与常量</td><td>625</td><td><code>clampRating</code>、<code>buildMonthGrid</code>、<code>colorHexToRgba</code>、<code>CAROUSEL_AUTOPLAY_INTERVAL</code> 等。它们是内核实现的一部分，实现变化时签名随之变化。所需默认值应从组件 props 的文档默认值读取，不应 import 常量再自行比对</td></tr><tr><td><code>@xihan-ui/headless</code> 的内部伴生类型</td><td>564</td><td><code>*Refs</code>（机器持有的 DOM 引用袋，46 个）、<code>ColorHsva</code>、<code>CascaderLevel</code> 等，是上述函数的参数与返回类型</td></tr><tr><td><code>xxxAnatomy</code> / <code>xxxMeta</code> / <code>xxxKeyboard</code> 三组导出对象</td><td>各 136</td><td>它们描述的 part 名单受约束（见第二节），但这三个对象本身的组织方式不受约束。部件名单以组件文档页的解剖表为准，不应 import 这些对象</td></tr><tr><td>Vue 的 <code>provide*</code> / <code>use*Context</code> 函数</td><td>115</td><td><a href="./../adapters/vue">Vue 适配器</a> 已写明父子组件之间的 provide / inject 是内部实现，不对外开放。需要下探时使用 <code>use&lt;家族&gt;()</code></td></tr><tr><td>Vue 的 <code>useTimelineItem</code></td><td>1</td><td>名字形似组合式函数，实际是 inject 管道，与上一行同类</td></tr><tr><td>适配器运行时底座</td><td>Vue 3 个、WC 8 个</td><td><code>createVueRuntime</code> / <code>createVueIdGenerator</code> / <code>vueNormalize</code>；<code>createLitRuntime</code> / <code>createSpreader</code> / <code>defineElement</code> / <code>discoverParts</code> / <code>wcNormalize</code> / <code>MachineController</code> 等。这些是适配器与内核之间的接缝，签名依赖的类型未从同一个包导出，无法构造调用</td></tr><tr><td>WC 的元素类导出 <code>Xh*Element</code></td><td>110</td><td>仅用于 <code>instanceof</code> 与手动 <code>customElements.define</code>，不支持 <code>extends</code>（基类不导出、<code>wire()</code> 是 protected abstract）。获取元素使用 <code>document.querySelector</code></td></tr><tr><td>WC 元素上的 <code>static partContract</code></td><td>136</td><td>部件校验的输入数据，实现细节</td></tr><tr><td><code>dist/</code> 内部文件名</td><td>—</td><td><code>element-Bx4xCiT2.js</code> 这类打包 chunk 每次构建都可能变化，不得 deep import</td></tr><tr><td><code>.d.ts</code> 的文件布局</td><td>—</td><td>类型从包入口获取，不引用具体 <code>.d.ts</code> 路径</td></tr><tr><td><code>ui/tooling/</code>、<code>ui/apps/playground-*</code></td><td>—</td><td>不发布</td></tr></tbody></table><hr><h2 id="二、解剖属性-data-scope-data-part" tabindex="-1">二、解剖属性（<code>data-scope</code> / <code>data-part</code>） <a class="header-anchor" href="#二、解剖属性-data-scope-data-part" aria-label="Permalink to &quot;二、解剖属性（`data-scope` / `data-part`）&quot;">​</a></h2><p>这是更换皮肤时最核心的一组名字，也是 Web Components 使用者手写 HTML 时书写的字符串。</p><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>档位</th></tr></thead><tbody><tr><td><code>data-scope</code> 取值（组件身份）</td><td>136</td><td><strong>受约束</strong>（新增第 137 个组件是 minor）</td></tr><tr><td><code>data-part</code> 取值（部件名）</td><td>290 个不同名字 / 1103 条「组件 × 部件」配对</td><td><strong>受约束</strong></td></tr><tr><td><code>data-xh-part</code>（WC 作者书写的角色声明）</td><td>属性名 1 个，取值即上面 290 个</td><td><strong>受约束</strong></td></tr><tr><td><code>meta.requiredParts</code>（必备部件）</td><td>300 条</td><td><strong>受约束</strong>（加条目 = major），方向见下</td></tr></tbody></table><p><code>data-scope</code> 的取值与三处完全同名，不做任何转换：headless 目录名、自定义元素标签 <code>xh-&lt;scope&gt;</code>、皮肤文件 <code>&lt;scope&gt;.css</code>。改动一处即四处同时破坏。</p><div class="warning custom-block"><p class="custom-block-title"><code>data-xh-part</code>、<code>data-xh-scroll</code>、墨色域与液态下层的声明是 <code>data-xh-</code> 前缀里仅有的例外</p><p>其余 <code>data-xh-*</code> 属性（<code>data-xh-scrollbar</code>、<code>data-xh-focus-guard</code>、<code>data-xh-inert-exempt</code> 等 53 个）是库自用标记，排除在承诺之外。例外都由作者书写：<code>data-xh-part</code> 是 Web Components 适配器唯一的作者输入 API；<code>data-xh-scroll</code> 只承诺「作者容器取得 reset 层的原生细条」（见<a href="./styling#组件内滚动">皮肤与样式分层</a>），不进任何组件契约，删除或改名同样按公开面破坏处理；<code>data-xh-ink</code> 与 <code>data-xh-ink-margin</code> 写在作者自己的彩色区块上，声明底色极性与余量（见<a href="/design/colors#彩色面与墨色域">色彩 · 彩色面与墨色域</a>），取值与语义按公开面承诺；<code>data-xh-backdrop</code> 与 <code>data-xh-backdrop-busy</code> 写在作者自己的图片、视频、画布区域上，声明液态面下层的明暗与杂乱（见<a href="./theme#液态材质">设计令牌与主题 · 液态材质</a>），同样按公开面承诺。作者书写 <code>data-xh-part=&quot;trigger&quot;</code> 是声明，元素接线后在同一节点写入 <code>data-scope</code> + <code>data-part</code> 是事实。皮肤匹配后者，后者不应手写。</p></div><h3 id="requiredparts-的方向是反的" tabindex="-1">requiredParts 的方向是反的 <a class="header-anchor" href="#requiredparts-的方向是反的" aria-label="Permalink to &quot;requiredParts 的方向是反的&quot;">​</a></h3><p>向 <code>requiredParts</code> 新增一条是收紧：原本可运行的 Light DOM 开始在 <a href="./diagnostics">诊断通道</a> 报 <code>wc.missing-part</code>。规则：</p><ul><li>删条目：任何版本都可以。</li><li>加条目：属于破坏性变更，只出现在 major，并且落地即按 <code>error</code> 报告。缺少必需角色节点恒发 <code>error</code>，没有先以 <code>warn</code> 过渡一个版本的档位。</li></ul><hr><h2 id="三、data-状态属性" tabindex="-1">三、<code>data-*</code> 状态属性 <a class="header-anchor" href="#三、data-状态属性" aria-label="Permalink to &quot;三、`data-*` 状态属性&quot;">​</a></h2><p><code>connect</code> 一共产出 237 个不同的 <code>data-*</code> 属性名、1662 条「组件 × 属性」配对。分两类。</p><h3 id="受约束-1" tabindex="-1">受约束 <a class="header-anchor" href="#受约束-1" aria-label="Permalink to &quot;受约束&quot;">​</a></h3><p>行为契约。这些不是样式钩子，删除会使功能静默失效：</p><table tabindex="0"><thead><tr><th>属性</th><th>作用</th></tr></thead><tbody><tr><td><code>data-value</code></td><td>集合型组件的条目值。行为层按它反查节点执行方向键导航，Web Components 使用者需手写在 <code>item</code> 节点上。删除后所有集合型组件的键盘导航静默失效</td></tr><tr><td><code>data-name</code></td><td>表单字段名（<code>form</code>）</td></tr><tr><td><code>data-index</code></td><td>条目序号（0 基）</td></tr></tbody></table><p>样式钩子。自带皮肤消费了 183 个属性名 / 793 条「皮肤 × 属性」配对（不含解剖的 <code>data-scope</code> / <code>data-part</code>），第三方皮肤参照的就是这一组：</p><table tabindex="0"><thead><tr><th>属性</th><th>选中它的皮肤份数</th></tr></thead><tbody><tr><td><code>data-size</code></td><td>79</td></tr><tr><td><code>data-state</code></td><td>64</td></tr><tr><td><code>data-disabled</code></td><td>58</td></tr><tr><td><code>data-variant</code></td><td>32</td></tr><tr><td><code>data-invalid</code></td><td>27</td></tr><tr><td><code>data-orientation</code> / <code>data-readonly</code></td><td>各 26</td></tr><tr><td><code>data-placement</code></td><td>22</td></tr><tr><td><code>data-highlighted</code></td><td>20</td></tr><tr><td><code>data-hidden</code> / <code>data-motion</code></td><td>各 18</td></tr><tr><td><code>data-dragging</code></td><td>13</td></tr><tr><td><code>data-tone</code></td><td>10</td></tr><tr><td><code>data-current</code> / <code>data-placeholder</code> / <code>data-empty</code> / <code>data-clearable</code> …</td><td>其余</td></tr><tr><td><code>data-cols-sm</code> / <code>-md</code> / <code>-lg</code> / <code>-xl</code></td><td>仅 <code>grid</code>，断点分档名受约束</td></tr></tbody></table><p>份数低不等于使用少：<code>data-tone</code> 的规则集中在 <code>tone.css</code> 一份文件中，浮层的 <code>data-placement</code> 同样集中在定位块中，逐份皮肤只在需要额外微调时才单独选中它们。属性名与取值的约束不按份数区分。</p><p>取值同样受约束。属性名变更会破坏皮肤，取值变更同样破坏且更隐蔽：<code>[data-state=&#39;open&#39;]</code> 在取值改为 <code>expanded</code> 之后仍是合法 CSS，只是永远不匹配。自带皮肤当前用到的 34 个 <code>data-state</code> 取值全部受约束：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>open  closed  checked  unchecked  indeterminate  on</span></span>\n<span class="line"><span>active  current  incomplete  visible  hidden  ready  empty  invalid  error</span></span>\n<span class="line"><span>completed  preparing  finishing  dismissing  picking  copying</span></span></code></pre></div><p>取值的真源是 <code>tooling/scripts/state-vocabulary.json</code>，按族登记了 7 个族共 38 个取值：同族互斥，一个部件同一时刻只取其中一个。上面 21 个是皮肤当前选中的取值，其余只在 DOM 上出现，尚无对应的皮肤规则。<code>check-state-vocabulary</code> 双向校验：<code>connect</code> 发出词汇表外的值报错，皮肤选中词汇表中不存在的值同样报错。</p><p>三条视觉轴的取值同理。<code>data-tone</code> 的合法值是 6 个，唯一真源是 <code>tone.css</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brand  neutral  success  warning  danger  info</span></span></code></pre></div><h3 id="排除-1" tabindex="-1">排除 <a class="header-anchor" href="#排除-1" aria-label="Permalink to &quot;排除&quot;">​</a></h3><p>其余 45 个 <code>data-*</code>（<code>data-lane</code>、<code>data-one-way</code>、<code>data-checked-count</code>、<code>data-sticking</code>、<code>data-file-size</code>、<code>data-modules</code> 等）：自带皮肤未选中它们，组件文档页也未记载。<code>check-state-vocabulary</code> 每次都会列出这批发射但零引用的属性名（连同上面 <code>data-value</code> / <code>data-index</code> 两个数据载体，共 47 个）。它们在 DOM 上存在，但不承诺稳定，随时可能改名或消失。需要依赖它们编写样式时，先提交 issue。</p><hr><h2 id="四、css-自定义属性与-layer" tabindex="-1">四、CSS 自定义属性与 <code>@layer</code> <a class="header-anchor" href="#四、css-自定义属性与-layer" aria-label="Permalink to &quot;四、CSS 自定义属性与 `@layer`&quot;">​</a></h2><h3 id="受约束-2" tabindex="-1">受约束 <a class="header-anchor" href="#受约束-2" aria-label="Permalink to &quot;受约束&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>说明</th></tr></thead><tbody><tr><td><code>@layer</code> 名与声明顺序</td><td>5</td><td><code>xihan.reset</code> → <code>xihan.tokens</code> → <code>xihan.motion</code> → <code>xihan.components</code> → <code>xihan.overrides</code>。改名、调序、增删中间层均为 major。<code>xihan.overrides</code> 刻意留空，专供使用方覆盖，不会作为未使用的层被清理</td></tr><tr><td>全局令牌 · 原语层</td><td>115</td><td><code>--xh-color-brand-500</code>、<code>--xh-space-4</code>、<code>--xh-radius-md</code>。皮肤中不应直接使用它们，但接入品牌轴必须写 <code>--xh-color-brand-*</code>，因此它们是公开的</td></tr><tr><td>全局令牌 · 语义层</td><td>302</td><td><code>--xh-bg-brand</code>、<code>--xh-fg-on-brand</code>、<code>--xh-control-h-md</code>、<code>--xh-shape-control</code>。主题定制的正门，见 <a href="./theme">设计令牌与主题</a></td></tr><tr><td>组件覆盖槽</td><td>4088（覆盖 135 个组件）</td><td><code>--xh-button-bg</code>、<code>--xh-button-h</code>、<code>--xh-dialog-max-w</code>。全部写成 <code>var(--xh-x-y, 默认值)</code> 形态，在 <code>:root</code> 中设置即可修改该组件</td></tr><tr><td>语气轴槽</td><td>12</td><td><code>--xh-_tone</code>、<code>--xh-_tone-on</code>、<code>--xh-_tone-hover</code>、<code>--xh-_tone-subtle</code>、<code>--xh-_tone-border</code> 等。这是自定义语气的唯一机制：写入 <code>[data-tone=&#39;premium&#39;] { --xh-_tone: gold; --xh-_tone-on: #000 }</code>，读取这批槽的 58 份皮肤随之生效。虽然带下划线前缀，但按受约束处理</td></tr><tr><td>关键帧名</td><td>40</td><td><code>xh-pop-in</code>、<code>xh-fade-out</code>、<code>xh-spin</code>。共享关键帧住在 <code>family/motion.css</code>（子入口 <code>@xihan-ui/styles/motion.css</code>），皮肤 <code>@import</code> 它；组件专属关键帧仍在各皮肤。在 <code>xihan.overrides</code> 层中重定义同名关键帧即可替换该段动画（关键帧名因此是公开面），所以改名与删名同样是 major</td></tr><tr><td>跨包内联属性</td><td>4</td><td><code>--xh-_truncate-lines</code>、<code>--xh-_float-button-offset</code>、<code>--xh-_tour-spotlight-radius</code>、<code>--xh-_carousel-autoplay-duration</code>。由 headless 写入内联 <code>style</code>，皮肤必须读取。整套更换皮肤时若不读取这些值，文本截断、浮动按钮贴边、引导目标圆角或轮播进度会失效，且不报任何错误</td></tr><tr><td><code>@xihan-ui/styles</code> 的 CSS 子路径</td><td>160</td><td><code>.</code>、<code>./index.css</code>、<code>./index.unlayered.css</code>，家族文件 <code>./action-control.css</code>、<code>./chart.css</code>、<code>./collection-item.css</code>、<code>./field-chrome.css</code>、<code>./swatch.css</code>、<code>./material.css</code>、<code>./motion.css</code>，与 148 条 <code>.css</code>：136 份组件皮肤加 <code>./layers.css</code>、<code>./tone.css</code>、<code>./reset.css</code>、<code>./overlay-arrow.css</code>、<code>./visually-hidden.css</code>、<code>./undefined.css</code>、<code>./focus.css</code>、<code>./label.css</code>、<code>./description.css</code>、<code>./pointer.css</code>、<code>./forced-colors.css</code></td></tr><tr><td><code>@xihan-ui/tokens</code> 的 CSS 子路径</td><td>2</td><td><code>./tokens.css</code>、<code>./tokens.json</code></td></tr></tbody></table><h3 id="排除-2" tabindex="-1">排除 <a class="header-anchor" href="#排除-2" aria-label="Permalink to &quot;排除&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>排除原因</th></tr></thead><tbody><tr><td>其余 <code>--xh-_</code> 私有槽</td><td>465</td><td>皮肤内部的回退中转（<code>--xh-_bg</code>、<code>--xh-_bg-hover</code>、<code>--xh-_mention-py</code> 等），变体只改槽位、不重写规则依赖它。不应在外部设置它们</td></tr><tr><td>令牌的取值</td><td>—</td><td><code>--xh-color-brand-500</code> 这个名字受约束，其对应的 <code>oklch()</code> 值不受约束。调色板随视觉迭代变化，这正是令牌存在的意义</td></tr><tr><td><code>index.css</code> 的内部结构</td><td>—</td><td>它是生成的扁平文件：家族配方只内联一次、排在皮肤之前，皮肤段的顺序即源序。段标记注释（<code>/* styles/xxx.css */</code>）只作阅读定位，不是承诺</td></tr><tr><td><code>index.unlayered.css</code> 的内部结构</td><td>—</td><td>它是同一源序的扁平镜像，不带 <code>@layer</code>。使用该入口时没有 <code>xihan.overrides</code> 覆盖槽位，层名承诺不适用</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">命名前缀不能反推归属</p><p><code>--xh-field-py</code> 形似 <code>field</code> 组件的覆盖槽，实际是全局语义令牌，<code>field.css</code> 本身并不使用它。同理 <code>--xh-text-*</code>（13 个全局文本令牌）与 <code>text-field</code> 的 48 条组件槽同前缀，<code>--xh-color-*</code>（43 个原语调色板令牌）与 <code>color-picker</code> 的 70 条组件槽同前缀。判断一条属性属于哪一档，看它在不在上表列的那 660 个全局令牌里，不按前缀推断。</p></div><hr><h2 id="五、自定义元素与-attribute" tabindex="-1">五、自定义元素与 attribute <a class="header-anchor" href="#五、自定义元素与-attribute" aria-label="Permalink to &quot;五、自定义元素与 attribute&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>档位</th></tr></thead><tbody><tr><td>自定义元素标签 <code>xh-*</code></td><td>139（<code>defineXhElements()</code> 注册 138 + <code>xh-background</code>）</td><td><strong>受约束</strong></td></tr><tr><td>注册函数</td><td>2（<code>defineXhElements</code>、<code>defineXhBackground</code>）</td><td><strong>受约束</strong></td></tr><tr><td>observed attribute</td><td>1357 条声明 / 393 个不同名字</td><td><strong>受约束</strong>（具体元素上的具体属性名）</td></tr><tr><td>attribute 名词汇表本身</td><td>393</td><td><strong>只增不减</strong>（新组件复用 <code>size</code> / <code>tone</code> / <code>dir</code> 不算破坏）</td></tr><tr><td><code>CustomEvent</code> 名</td><td>96 个名字 / 210 条「元素 × 事件」</td><td><strong>受约束</strong></td></tr><tr><td>事件传播语义</td><td><code>bubbles: true, composed: true</code>（195 处中 193 处）</td><td><strong>受约束</strong>。取消冒泡会使祖先节点上的事件委托静默失效。例外是名为 <code>submit</code> 的事件（<code>xh-prompt-input</code> / <code>xh-question-flow</code>）：与原生表单提交同名，一律不冒泡，避免被祖先 <code>&lt;form&gt;</code> 视为自身的提交</td></tr><tr><td>事件 <code>detail</code> 形状</td><td>188 个 <code>*Details</code> 类型</td><td><strong>受约束</strong>，等同于 headless 的同名类型</td></tr><tr><td><code>attribute: false</code> 的 JS 字段</td><td>223 条（涉及 76 个字段名）</td><td><strong>受约束</strong>。<code>collection</code>、<code>translations</code>、<code>validate</code>、<code>filter</code> 等只能通过 JS 赋值，HTML 中无法表达：不是每个 property 都有对应 attribute</td></tr><tr><td>命令式方法</td><td>97（分布在 50 个元素）</td><td><strong>受约束</strong>，含参数与返回类型</td></tr></tbody></table><p>命令式方法全清单：</p><table tabindex="0"><thead><tr><th>元素</th><th>方法</th></tr></thead><tbody><tr><td><code>xh-form</code></td><td><code>setFieldValue</code> <code>setFieldError</code> <code>clearErrors</code> <code>submit</code> <code>reset</code> <code>getFieldId</code> <code>getFieldValue</code> <code>getFieldError</code></td></tr><tr><td><code>xh-notification</code></td><td><code>create</code> <code>updateItem</code> <code>dismiss</code> <code>dismissAll</code> <code>getItemsByPlacement</code></td></tr><tr><td><code>xh-file-upload</code></td><td><code>openFilePicker</code> <code>setFiles</code> <code>addFiles</code> <code>deleteFile</code> <code>clear</code></td></tr><tr><td><code>xh-timer</code></td><td><code>start</code> <code>pause</code> <code>resume</code> <code>reset</code></td></tr><tr><td><code>xh-virtualizer</code></td><td><code>scrollToIndex</code> <code>measureElement</code> <code>measure</code></td></tr><tr><td><code>xh-signature-pad</code></td><td><code>clear</code> <code>toSvg</code></td></tr><tr><td><code>xh-log</code></td><td><code>scrollToBottom</code></td></tr><tr><td><code>xh-tour</code></td><td><code>remeasure</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">布尔 attribute 是三态的</p><p><code>modal=&quot;false&quot;</code> 表示关闭，不写表示交由组件决定，这与原生 HTML 布尔属性（写出即为真）不同。把三态转换器换回原生语义是不改名字的语义收窄，按 major 处理。</p></div><p>以下与包结构有关的事实同样在承诺内：</p><ul><li>元素在 <code>@xihan-ui/web-components/define</code>，不在包主入口。<code>defineXhElements()</code> 是全量注册：调用即注册全部 138 个元素，没有逐个的 <code>defineXhButton()</code>。（补充细粒度 define 是 minor；补充后 <code>defineXhElements</code> 的全量语义即成为承诺。）</li><li><code>xh-background</code> 单独在 <code>@xihan-ui/web-components/backgrounds</code>，因为它依赖可选 peer。把它移入 <code>./define</code> 会强制所有使用方安装 WebGL 引擎，属于破坏性变更。</li><li>元素全部是 Light DOM，没有 shadow root，<code>::part()</code> 不生效。CEM 中的 <code>cssParts</code> 条目在本包读作 <code>data-xh-part</code>，不是 shadow part。</li></ul><hr><h2 id="六、什么算破坏性变更" tabindex="-1">六、什么算破坏性变更 <a class="header-anchor" href="#六、什么算破坏性变更" aria-label="Permalink to &quot;六、什么算破坏性变更&quot;">​</a></h2><p>正例（major）与反例（minor / patch）对照，按介质各举数条。</p><h3 id="js-导出" tabindex="-1">JS 导出 <a class="header-anchor" href="#js-导出" aria-label="Permalink to &quot;JS 导出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td>删除或改名任一 <code>Xh*</code> 组件（含 <code>XhTreeSelectBranchIndicator</code> 等低频部件）</td><td>新增组件、新增部件</td></tr><tr><td><code>connectAccordion</code> 的返回值把 <code>getRootProps</code> 改成 <code>getProps</code></td><td>给 <code>connectAccordion</code> 加一个新的 getter</td></tr><tr><td><code>SelectProps</code> 新增一个必填字段，或把可选字段改为必填</td><td><code>SelectProps</code> 新增可选字段</td></tr><tr><td><code>SelectApi</code> 删除一个 getter</td><td><code>SelectContext</code> 新增一个可选字段</td></tr><tr><td>把 <code>useSelect()</code> 的返回从 <code>ComputedRef&lt;Api&gt;</code> 换成其他容器</td><td>新增 <code>useXxx</code></td></tr><tr><td>把某个 prop 从裸 <code>Boolean</code> 改成 <code>default: undefined</code></td><td>给某个 prop 补文档</td></tr><tr><td>从某个组件的 <code>emits</code> 数组中删除一个名字</td><td>向 <code>emits</code> 新增一个名字</td></tr></tbody></table><h3 id="解剖与-data" tabindex="-1">解剖与 <code>data-*</code> <a class="header-anchor" href="#解剖与-data" aria-label="Permalink to &quot;解剖与 `data-*`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td><code>data-part</code> 从 <code>indicator</code> 改成 <code>marker</code></td><td>给某个组件新增一个可选部件</td></tr><tr><td>把 <code>item-text</code> 改成 <code>itemText</code>（分词/大小写变化）</td><td>皮肤内部改用其他选择器组合实现同样的视觉</td></tr><tr><td>某个组件不再输出 <code>data-size</code> / <code>data-tone</code></td><td>给某个组件补上原本没有的 <code>data-tone</code></td></tr><tr><td><code>data-state</code> 的取值从 <code>open</code> 改成 <code>expanded</code></td><td>新增一个 <code>data-state</code> 取值</td></tr><tr><td>把 <code>data-disabled</code> 从「存在即禁用」改成 <code>data-disabled=&quot;true&quot;</code></td><td>—</td></tr><tr><td>删除 <code>data-value</code></td><td>删除 <code>data-lane</code>（在排除清单中）</td></tr></tbody></table><h3 id="css" tabindex="-1">CSS <a class="header-anchor" href="#css" aria-label="Permalink to &quot;CSS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td><code>--xh-button-h</code> 改名成 <code>--xh-button-block-size</code></td><td>新增 <code>--xh-button-letter-spacing</code></td></tr><tr><td>删除 <code>--xh-radius-xl</code>（即使库内部未使用）</td><td>调整 <code>--xh-color-brand-500</code> 的 <code>oklch()</code> 值</td></tr><tr><td>把 <code>var(--xh-alert-px, …)</code> 改为直接写语义令牌（等于取消该覆盖点）</td><td>给某条规则补充 <code>@supports</code> 兜底</td></tr><tr><td>调整 <code>@layer</code> 声明顺序</td><td>在 <code>xihan.components</code> 里加规则</td></tr><tr><td>删除 <code>./tone.css</code> 子路径</td><td>新增 <code>./&lt;新组件&gt;.css</code> 子路径</td></tr></tbody></table><h3 id="自定义元素" tabindex="-1">自定义元素 <a class="header-anchor" href="#自定义元素" aria-label="Permalink to &quot;自定义元素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td><code>xh-empty-state</code> 改名成 <code>xh-empty</code></td><td>新增 <code>xh-xxx</code> 元素</td></tr><tr><td>某元素的 <code>observedAttributes</code> 减少一条</td><td>给某元素新增 attribute</td></tr><tr><td>把 <code>read-only</code> 改写成 <code>readonly</code></td><td>把某个 <code>attribute: false</code> 的字段反向暴露成 attribute</td></tr><tr><td>事件名 <code>value-change</code> 改成 <code>change</code></td><td>新增事件名</td></tr><tr><td>把某个事件的 <code>bubbles</code> 改成 <code>false</code></td><td>补 <code>HTMLElementEventMap</code> 类型增强</td></tr><tr><td><code>xh-notification.create()</code> 从返回 <code>string</code> 改成返回对象</td><td>给 <code>xh-form</code> 新增一个方法</td></tr><tr><td>把某个可选 part 提升为 <code>requiredParts</code></td><td>新增一个可选 part</td></tr></tbody></table><h3 id="支持面" tabindex="-1">支持面 <a class="header-anchor" href="#支持面" aria-label="Permalink to &quot;支持面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td>抬高 Node 下限</td><td>降低 Node 下限</td></tr><tr><td>抬高浏览器硬底线（使用一个无兜底的新 CSS 特性）</td><td>新增一个带退化路径的增强特性</td></tr><tr><td>收窄 <code>vue</code> peer 区间（加上限、抬下限）</td><td>放宽 peer 区间</td></tr><tr><td>撤销 ESM 导出条件</td><td>增加 CJS 导出条件</td></tr></tbody></table><hr><h2 id="七、移除流程" tabindex="-1">七、移除流程 <a class="header-anchor" href="#七、移除流程" aria-label="Permalink to &quot;七、移除流程&quot;">​</a></h2><p>本库不设废弃期，也不保留兼容层。改名直接改，删除直接删：不为旧写法保留别名、不把旧名放入兜底链、不在源码中标注 <code>@deprecated</code> 延长存续。在一个 major 中读到的名字就是当时唯一存在的名字。</p><p>移除动作集中在 major，一律出现在更新日志顶部、单列一节，逐条写明旧名与替换写法，这是唯一的迁移材料。</p><p>四种介质需要单独说明：<code>data-*</code>、CSS 自定义属性、<code>@layer</code> 名、元素 attribute 没有 IDE 提示，改名之后对应选择器只会静默失配，不报错也不降级。它们唯一的告知渠道是更新日志，因此每次移除都在 changeset 中逐条列出旧名与替换写法，使用方可据此在自己的代码库中全文搜索。</p><hr><h2 id="八、支持面" tabindex="-1">八、支持面 <a class="header-anchor" href="#八、支持面" aria-label="Permalink to &quot;八、支持面&quot;">​</a></h2><p>收窄支持面按破坏性变更处理，放宽随时可以。</p><h3 id="运行时" tabindex="-1">运行时 <a class="header-anchor" href="#运行时" aria-label="Permalink to &quot;运行时&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th><th>变更规则</th></tr></thead><tbody><tr><td>Node（安装并运行本库）</td><td><strong>≥ 18</strong></td><td>抬高 = major。产物实际用到的最高特性是 <code>Object.hasOwn</code>（Node 16.9），<code>&gt;=18</code> 留了余量</td></tr><tr><td>Node（开发本仓库）</td><td>≥ 24，pnpm ≥ 11</td><td>与上一行无关，随时可变</td></tr><tr><td>模块格式</td><td><strong>ESM only</strong></td><td>无 CJS、无 node10 解析条件。包中 <code>main</code> / <code>module</code> 字段存在但指向 ESM 文件，是给旧式 bundler 的别名，不代表可以 <code>require</code></td></tr><tr><td>包管理器</td><td>无要求</td><td>—</td></tr></tbody></table><h3 id="浏览器" tabindex="-1">浏览器 <a class="header-anchor" href="#浏览器" aria-label="Permalink to &quot;浏览器&quot;">​</a></h3><p>硬底线由三个无兜底的 CSS 特性决定：<code>@layer</code>（125/125 个样式文件使用，不识别它的解析器会丢弃整块）、<code>oklch()</code>（<code>tokens.css</code> 中 63 处，是唯一颜色来源）、<code>color-mix()</code>。</p><table tabindex="0"><thead><tr><th>浏览器</th><th>硬底线</th><th>完整保真</th></tr></thead><tbody><tr><td>Chrome / Edge</td><td><strong>111</strong></td><td>111</td></tr><tr><td>Firefox</td><td><strong>113</strong></td><td>121（<code>:has()</code>）</td></tr><tr><td>Safari</td><td><strong>16.2</strong></td><td>16.4</td></tr></tbody></table><p>测试承诺：当前正式版，外加 Chromium 与 Safari 各向前两个大版本、Firefox ESR。硬底线只在 major 中抬高。</p><p>低于硬底线不会降级，而是无样式：皮肤中刻意不写兜底值，令牌缺席是缺陷而不是降级。</p><p>高于硬底线又无从兜底的特性，皮肤一律不用，由 <code>check-css-floor</code> 的拒绝名单拦截（<code>@scope</code>、<code>@starting-style</code>、嵌套选择器等）。其中容易误写的一条：</p><table tabindex="0"><thead><tr><th>特性</th><th>最早完整支持</th><th>底线内的引擎不认时</th><th>皮肤的写法</th></tr></thead><tbody><tr><td>媒体查询区间写法 <code>(width &lt; 768px)</code></td><td>Chrome 104 / Firefox 63 / Safari 16.4</td><td>Safari 16.2 / 16.3 把整条查询判作不成立，块内规则静默丢失</td><td>断点只写 <code>(min-width: …)</code>，窄档专属规则写它的补集 <code>not all and (min-width: …)</code></td></tr></tbody></table><p>可选增强层（不支持时按下表退化；新增增强特性不算破坏，前提是同时提供退化路径）：</p><table tabindex="0"><thead><tr><th>特性</th><th>Chrome</th><th>Firefox</th><th>Safari</th><th>不支持时</th></tr></thead><tbody><tr><td><code>:has()</code></td><td>105</td><td>121</td><td>15.4</td><td>少量间距/gutter 微调失效</td></tr><tr><td><code>scrollbar-gutter</code></td><td>94</td><td>97</td><td>18.2</td><td>滚动条出现时轻微位移</td></tr><tr><td><code>dvh</code> / <code>svh</code> / <code>lvh</code></td><td>108</td><td>101</td><td>15.4</td><td>回落到 <code>vh</code></td></tr><tr><td><code>text-wrap: balance</code></td><td>114</td><td>121</td><td>17.5</td><td>标题按默认换行</td></tr><tr><td><code>light-dark()</code></td><td>123</td><td>120</td><td>17.5</td><td>代码块语法色退化成单色</td></tr><tr><td><code>field-sizing</code></td><td>123</td><td>152</td><td>26.2</td><td><code>prompt-input</code> 输入框退化成固定行数</td></tr></tbody></table><p>Web Components 侧不构成额外约束：全部 Light DOM，不使用 shadow DOM、<code>ElementInternals</code>、<code>adoptedStyleSheets</code>，平台要求只到 Custom Elements v1。</p><h3 id="宿主框架" tabindex="-1">宿主框架 <a class="header-anchor" href="#宿主框架" aria-label="Permalink to &quot;宿主框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包</th><th>peer</th><th>规则</th></tr></thead><tbody><tr><td><code>@xihan-ui/vue</code></td><td><code>vue: ^3.5.0</code></td><td>下限由 <code>useId</code> 决定（Vue 3.5 引入）。收窄为 major，放宽为 minor</td></tr><tr><td><code>@xihan-ui/vue</code>、<code>@xihan-ui/web-components</code></td><td><code>@xihan-ui/backgrounds</code>（optional）</td><td>不使用背景效果时无需安装</td></tr><tr><td><code>@xihan-ui/vue</code></td><td><code>@xihan-ui/sound</code>（optional）</td><td>不使用音效时无需安装</td></tr><tr><td><code>@xihan-ui/web-components</code></td><td>无框架 peer</td><td>原生自定义元素，不要求任何框架</td></tr><tr><td>其余 15 个包</td><td>无</td><td>—</td></tr></tbody></table><hr><h2 id="九、包的稳定性分级" tabindex="-1">九、包的稳定性分级 <a class="header-anchor" href="#九、包的稳定性分级" aria-label="Permalink to &quot;九、包的稳定性分级&quot;">​</a></h2><p>锁步发版意味着版本号不反映稳定性，因此单独列表。</p><p>下面两张表覆盖全部 18 个包，每个包必在其中一张中；门禁比对两张表的包名与 <code>packages/</code> 下的公开包，新增包未定级即构建失败。</p><h3 id="稳定" tabindex="-1">稳定 <a class="header-anchor" href="#稳定" aria-label="Permalink to &quot;稳定&quot;">​</a></h3><p>破坏性变更只出现在 major，移除按上文流程执行。</p><table tabindex="0"><thead><tr><th>包</th><th>说明</th></tr></thead><tbody><tr><td><code>@xihan-ui/vue</code></td><td>1056 个组件、104 个组合式函数</td></tr><tr><td><code>@xihan-ui/react</code></td><td>组件与 hooks（铺开中，公开面随批次增长）</td></tr><tr><td><code>@xihan-ui/web-components</code></td><td>139 个自定义元素</td></tr><tr><td><code>@xihan-ui/headless</code></td><td><code>connect*</code> / <code>*Machine</code> / 各类公开类型；内部算子在排除清单里</td></tr><tr><td><code>@xihan-ui/styles</code></td><td>136 份组件皮肤、5 个层名</td></tr><tr><td><code>@xihan-ui/tokens</code></td><td>660 个令牌名，外加 <code>./runtime</code> 的主题控制器与种子色 API</td></tr><tr><td><code>@xihan-ui/icons</code></td><td>图标集</td></tr><tr><td><code>@xihan-ui/core</code></td><td>只有被适配器与 headless 公开消费的那部分（<code>createAnatomy</code>、<code>createNormalizer</code>、归一化规则、状态机公开面），含 <code>data-value</code> 这条集合导航契约；另有 <code>./date</code> 子入口的全部导出（<code>PlainDate</code> / <code>PlainTime</code> / <code>PlainDateTime</code>、时区换算、周规则、边界函数与格式化器）</td></tr><tr><td><code>@xihan-ui/position</code></td><td><code>createPositionEngine</code> 与它的选项；其余 9 个导出是内部算子</td></tr><tr><td><code>@xihan-ui/motion</code></td><td>缓动名、时长常量、<code>animate</code>、补间与弹簧算子。三值与令牌层同源（<code>check-motion-source</code> 比对），<code>core</code> / <code>headless</code> 与各适配器均建立在它之上，改名会先破坏库自身</td></tr><tr><td><code>@xihan-ui/pointer</code></td><td><code>createPointerSession</code> / <code>createMultiPointerSession</code> 与四层几何纯函数。<code>headless</code> 与各适配器的拖拽、缩放、划动全部经由它，同上</td></tr></tbody></table><h3 id="实验" tabindex="-1">实验 <a class="header-anchor" href="#实验" aria-label="Permalink to &quot;实验&quot;">​</a></h3><p>这七个包的破坏性变更可以出现在 minor 中，不适合用于不易升级的生产代码。</p><table tabindex="0"><thead><tr><th>包</th><th>仍在变化的原因</th></tr></thead><tbody><tr><td><code>@xihan-ui/viz</code></td><td>图表组件按期接入，比例尺、形状、场景与过渡的签名随组件落地仍会调整</td></tr><tr><td><code>@xihan-ui/code-highlight</code></td><td>承诺面是 <code>HighlighterPort</code> 端口，自研分词器（<code>tokenizeCode</code>、<code>langSpecOf</code>、<code>LangSpec</code>）随时可能整体替换</td></tr><tr><td><code>@xihan-ui/markdown</code></td><td>公开面是 <code>createStreamRenderer</code> 与它的三个类型，外加 <code>blockKind</code> / <code>fenceLang</code> / <code>isFenceClosed</code> / <code>LIVE_BLOCK_KEY</code> 四个切块算子；解析、切块、缓存的中间件随时可能变化</td></tr><tr><td><code>@xihan-ui/chat-stream</code></td><td>AI 会话协议类型（<code>UIMessage</code>、<code>TextPart</code> 等）跟随上游生态演进</td></tr><tr><td><code>@xihan-ui/backgrounds</code></td><td>效果参数与点云 API 仍在调整；通用短名（<code>bool</code> / <code>num</code> / <code>str</code> / <code>rgb</code>）不是公开 API</td></tr><tr><td><code>@xihan-ui/animations</code></td><td>公开面是 <code>MotionSpec</code> 的字段与 <code>BUILTIN_MOTION_NAMES</code> 里的预设名。预设表随组件接入继续调整，预设改名没有门禁拦截：它不是导出名，删除不会被报告</td></tr><tr><td><code>@xihan-ui/sound</code></td><td>同上：<code>SoundSpec</code> 的层与包络字段、三套主题、<code>BUILTIN_SOUND_NAMES</code> 中的预设名仍在调整</td></tr></tbody></table><hr><h2 id="门禁覆盖范围" tabindex="-1">门禁覆盖范围 <a class="header-anchor" href="#门禁覆盖范围" aria-label="Permalink to &quot;门禁覆盖范围&quot;">​</a></h2><h3 id="已由门禁保证" tabindex="-1">已由门禁保证 <a class="header-anchor" href="#已由门禁保证" aria-label="Permalink to &quot;已由门禁保证&quot;">​</a></h3><p>六种介质的改名即 major 已有门禁保证。<code>pnpm gate:surface</code> 运行的 <code>check-public-surface</code> 以入库基线（<code>ui/tooling/public-surface.json</code>，16366 个名字）比对当前状态： 基线中有而当前没有，即为删除或改名，构建失败。新增一律放行，因为新增是 minor。</p><p>覆盖：包名与 198 条子入口、8513 个导出名、136 个 <code>data-scope</code> 与 1103 条部件配对、 136 个组件的 1763 个 prop 名、239 种 <code>data-*</code>、34 个 <code>data-state</code> 取值、660 个令牌、 5 个 <code>@layer</code> 名、4088 个组件覆盖槽、138 个自定义元素及其 attribute 与事件。</p><p>prop 名一维是后补的：在它加入之前，修改一个 prop 名（实测 <code>transfer</code> 的 <code>items</code> 改 <code>collection</code>、<code>splitter</code> 的 <code>size</code> 改 <code>sizes</code>）其余门禁全程沉默。它的事实源是无头内核的 <code>&lt;组件&gt;Schema[&#39;props&#39;]</code>，各适配器的 props 均按它展开。</p><p>它的必要性可以复现：把 <code>switch</code> 的 <code>thumb</code> 改名 <code>knob</code>，其余门禁全部通过， 只有这一道拦截；把 <code>switch</code> 的 <code>checked</code> 改名 <code>isChecked</code>，同样只有它报出 「组件 prop switch: checked」。删除一个语义令牌、修改一个组件覆盖槽名同理。</p><p>确需破坏性变更时，运行 <code>pnpm surface:update</code> 更新基线并在 changeset 中说明： 门禁拦截的是无意删除，不是有意的 major。</p><div class="warning custom-block"><p class="custom-block-title">基线锁定的名字比本页承诺的范围宽</p><p>基线是所有可写出名字的机械快照，不区分档位：本页归入排除的成员同样在内，包括 headless 的 625 个内部算子与常量、564 个伴生类型、<code>*Anatomy</code> / <code>*Meta</code> / <code>*Keyboard</code> 三组导出对象， 以及六个实验包的全部导出。政策允许随时删改它们，但删除仍会触发门禁。 行使这份删除权时先运行 <code>pnpm surface:update</code> 更新基线，这不是破坏性变更， changeset 按 patch / minor 记录即可：更新基线这一动作本身不代表 major。</p></div><p>另有三道门禁把原本依赖自觉的条款转为机器检查。<code>check-css-floor</code> 保证浏览器硬底线： <code>.browserslistrc</code> 记录底线，拒绝名单拦截 <code>@scope</code>、媒体查询区间写法等无兜底的抬底线特性， <code>light-dark()</code> / <code>dvh</code> / <code>lh</code> 必须带级联兜底。<code>check-version-lock</code> 保证 18 包锁步：任何一个 package.json 的 version 与其余不同，门禁直接失败。<code>check-wiring</code> 保证检查系统自身：新增的 check 脚本未接入 <code>pnpm gate</code> 等同于未编写，死引用同样被拦截。</p><p>三条视觉轴已收敛为联合类型，<code>tone</code> / <code>size</code> / <code>variant</code> 不再是裸 <code>string</code>， 写错取值在编译期报错。Vue 事件载荷已有类型，101 个组件的 <code>emits</code> 全是对象式， 产物 <code>.d.ts</code> 中不再出现 <code>(...args: any[]) =&gt; any</code>。</p><h3 id="尚无门禁的条款" tabindex="-1">尚无门禁的条款 <a class="header-anchor" href="#尚无门禁的条款" aria-label="Permalink to &quot;尚无门禁的条款&quot;">​</a></h3><p>以下条款目前没有门禁。</p><table tabindex="0"><thead><tr><th>条款</th><th>现状</th><th>计划补充的机制</th></tr></thead><tbody><tr><td>Vue 作用域插槽载荷</td><td>带载荷的插槽已声明 <code>slots:</code> 选项，由 <code>check-slot-types</code> 门禁的四条判据保证（缺声明 / 键非可选 / 值非函数 / 声明未用）。仅渲染无载荷插槽的部件仍不声明，消费方写错 slot 名不会报错</td><td>无载荷插槽也补充声明，或明确只有带载荷的插槽进入契约</td></tr><tr><td>移除提示（CSS / <code>data-*</code> / attribute / 层名）</td><td>这四种介质没有 IDE 提示：名字移除之后，消费方的声明只是静默失配，既不报错也不降级。唯一的告知渠道是更新日志，因此每次移除都在 changeset 中逐条列出旧名与替换写法，供使用方在自己的代码库中全文搜索</td><td>无</td></tr><tr><td>浏览器硬底线</td><td>已落地：<code>.browserslistrc</code> 记录硬底线，<code>check-css-floor</code> 门禁拒绝抬底线的无兜底特性（<code>@scope</code>、媒体查询区间写法等），并校验 <code>light-dark()</code> / <code>dvh</code> / <code>lh</code> 的级联兜底</td><td>拒绝名单改动时联动本页支持面表格的提醒</td></tr><tr><td>「18 个包必须同版本」</td><td><code>check-version-lock</code> 门禁保证 18 个 package.json 同版本。运行期一侧只在 dev 有提示：三个适配器启动时调用 <code>checkLockstepVersion</code>，自身版本与 core 不一致时经诊断通道发出一条 <code>warn</code>；生产构建中跳过，且只比对适配器与 core 两个版本，不是全部 18 个</td><td>提升为 peer，或把运行期比对扩展到全部包</td></tr></tbody></table><p>本页内容与实际行为不符时按缺陷处理，请提交 issue。</p>',123)])])}const b=t(a,[["render",r]]);export{u as __pageData,b as default};
